:"https://www.google.com/maps/search/?api=1&query=31.627747,-7.990592","offre_emploi":"Non","offre_stage":"Non","id":440},{"nom":"Riad Palau Marrakech","domaine":"Tourisme & Hôtellerie","sous_domaine":"-","categorie":"Maison d'hôtes","telephone":"Non disponible","email":"contact@riadpalau.com","site_web":"https://www.riadpalau-marrakech.com/","adresse":"31 derb massaoud, Marrakech","latitude":31.6367933,"longitude":-7.9913068,"note":null,"nombre_avis":null,"priorite":"Moyenne","score_priorite":4,"google_maps":"https://www.google.com/maps/search/?api=1&query=31.636793,-7.991307","offre_emploi":"Non","offre_stage":"Non","id":441},{"nom":"Riad Azoulay","domaine":"Tourisme & Hôtellerie","sous_domaine":"-","categorie":"Maison d'hôtes","telephone":"Non disponible","email":"info@riad-azoulay.com","site_web":"https://www.riad-azoulay.com/","adresse":"3, Derb Jamaa El Kibir, 40000, Marrakech","latitude":31.6195643,"longitude":-7.9831444,"note":null,"nombre_avis":null,"priorite":"Moyenne","score_priorite":4,"google_maps":"https://www.google.com/maps/search/?api=1&query=31.619564,-7.983144","offre_emploi":"Non","offre_stage":"Non","id":442},{"nom":"Palm Plaza Hotel and Spa","domaine":"Tourisme & Hôtellerie","sous_domaine":"-","categorie":"Hôtel","telephone":"Non disponible","email":"reservation@hotelpalmplaza.com","site_web":"https://www.hotelpalmplaza.com/","adresse":"Non disponible","latitude":31.5945006,"longitude":-7.9898071,"note":null,"nombre_avis":null,"priorite":"Moyenne","score_priorite":4,"google_maps":"https://www.google.com/maps/search/?api=1&query=31.594501,-7.989807","offre_emploi":"Non","offre_stage":"Non","id":443}]$companies_20261003$::jsonb)
as input(id integer, nom text, domaine text, sous_domaine text, categorie text, telephone text, email text, site_web text, adresse text, latitude numeric, longitude numeric, note numeric, nombre_avis integer, priorite text, score_priorite numeric, google_maps text, offre_emploi text, offre_stage text);
do $validation$
begin
  if (select count(*) from incoming_companies_20261003) <> 436
    or (select count(distinct id) from incoming_companies_20261003) <> 436
    or exists(select 1 from public.entreprises e join incoming_companies_20261003 i using(id)
      where e.google_maps is distinct from i.google_maps and e.nom is distinct from i.nom)
  then raise exception 'Company import validation failed; transaction rolled back'; end if;
end
$validation$;
insert into public.entreprises (id, nom, domaine, sous_domaine, categorie, telephone, email, site_web, adresse, latitude, longitude, note, nombre_avis, priorite, score_priorite, google_maps, offre_emploi, offre_stage, is_active)
select id, nom, domaine, sous_domaine, categorie, telephone, email, site_web, adresse, latitude, longitude, note, nombre_avis, priorite, score_priorite, google_maps, offre_emploi, offre_stage, true from incoming_companies_20261003
on conflict (id) do update set
  nom = excluded.nom,
  domaine = excluded.domaine,
  sous_domaine = excluded.sous_domaine,
  categorie = excluded.categorie,
  telephone = excluded.telephone,
  email = excluded.email,
  site_web = excluded.site_web,
  adresse = excluded.adresse,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  note = excluded.note,
  nombre_avis = excluded.nombre_avis,
  priorite = excluded.priorite,
  score_priorite = excluded.score_priorite,
  google_maps = excluded.google_maps,
  offre_emploi = excluded.offre_emploi,
  offre_stage = excluded.offre_stage,
  is_active = true;
update public.entreprises e set is_active = false
where e.is_active and not exists(select 1 from incoming_companies_20261003 i where i.id=e.id);
do $sequence$
declare seq text;
begin
  seq := pg_get_serial_sequence('public.entreprises','id');
  if seq is not null then perform setval(seq, (select max(id) from public.entreprises), true); end if;
end
$sequence$;
do $verification$
begin
  if (select count(*) from public.entreprises where is_active) <> 436
    or exists(select 1 from incoming_companies_20261003 i left join public.entreprises e using(id)
      where e.id is null or not e.is_active or e.nom is distinct from i.nom)
  then raise exception 'Company import verification failed; transaction rolled back'; end if;
end
$verification$;
commit;
select count(*) filter(where is_active) as entreprises_actives,
       count(*) filter(where not is_active) as entreprises_archivees,
       (select count(*) from company_import_backups.entreprises_before_20261003) as entreprises_sauvegardees
from public.entreprises;
